function currentLang(){return localStorage.getItem('assembleone_mobile_lang')||'en'}
function setLang(lang){localStorage.setItem('assembleone_mobile_lang',lang);paintLangButtons();renderAll();applyI18n()}
function t(key,params){const lang=currentLang();let s=(I18N[lang]&&I18N[lang][key])||I18N.en[key]||key;if(params)params.forEach((v,i)=>{s=s.split('{'+i+'}').join(v)});return s}
// Stage 2 of the multilingual audit: shared room-type key/label split so Studio
// and Mobile store the exact same stable English `type` value (used for saved
// data and Studio<->Mobile syncing) but can each show a translated label for
// it. roomTypeKeyMap/roomTypeLabel are copied from Mobile's existing, working
// version, with one behaviour change: an unmapped type (a legacy or custom
// room whose stored type isn't one of the 16 known values) now falls back to
// showing its own raw value instead of a raw, untranslated "roomType.xxx" key
// string -- this path was never exercised by Mobile's fixed-picker usage, so
// it's a pure safety improvement, not a change to any real existing behaviour.
const roomTypeKeyMap={"Kitchen":"kitchen","Living Room":"livingRoom","TV Wall":"tvWall","Master Bedroom":"masterBedroom","Bedroom":"bedroom","Kids Bedroom":"kidsBedroom","Dressing Room":"dressingRoom","Bathroom":"bathroom","Office":"office","Laundry":"laundry","Utility Room":"utilityRoom","Hallway":"hallway","Under Stairs":"underStairs","Wine Room":"wineRoom","Library":"library","Custom":"custom"};
function roomTypeLabel(n){const key=roomTypeKeyMap[n];return key?t('roomType.'+key):(n||'')}
// Stage 4, Site Planner section: shared trade key/label split, same pattern as
// roomTypeKeyMap/roomTypeLabel above. Moved here from Mobile.html (which already
// had this working, tested pattern for its own trade-tagged site messages) so
// Studio's Site Planner -- which stores the exact same `trade` value on pins,
// stages and messages -- can reuse it instead of building a second copy. Adds
// two entries Mobile's original map didn't need: "Steelworker" (a Studio-only
// trade option) and "Measurement" (Site Planner's own pseudo-trade for
// measurement pins).
const tradeKeyMap={"Builder":"builder","Bricklayer":"bricklayer","Plumber":"plumber","Electrician":"electrician","Decorator":"decorator","Carpenter":"carpenter","Wardrobes":"wardrobes","Flooring":"flooring","Kitchen Installer":"kitchenInstaller","Tiler":"tiler","HVAC / Air Conditioning":"hvac","Heating":"heating","Windows":"windows","Doors":"doors","Roofer":"roofer","Steelworker":"steelworker","Landscaper":"landscaper","Supplier":"supplier","Client":"client","Other":"other","Measurement":"measurement"};
function tradeLabel(n){const key=tradeKeyMap[n];return key?t('trade.'+key):(n||'')}
const LANG_NAMES={en:'English',es:'Español',da:'Dansk',de:'Deutsch',fr:'Français',ro:'Română',it:'Italiano',pt:'Português',nl:'Nederlands',pl:'Polski'};
const LANG_FLAGS={
 en:'<svg viewBox="0 0 60 36"><rect fill="#21468B" height="36" width="60"/><path d="M0 0L60 36M60 0L0 36" stroke="#fff" stroke-width="8"/><path d="M0 0L60 36M60 0L0 36" stroke="#C8102E" stroke-width="4"/><path d="M30 0v36M0 18h60" stroke="#fff" stroke-width="12"/><path d="M30 0v36M0 18h60" stroke="#C8102E" stroke-width="7"/></svg>',
 es:'<svg viewBox="0 0 60 36"><rect fill="#AA151B" height="36" width="60"/><rect fill="#F1BF00" height="18" width="60" y="9"/></svg>',
 da:'<svg viewBox="0 0 60 36"><rect fill="#C60C30" height="36" width="60"/><rect fill="#fff" height="36" width="5" x="18"/><rect fill="#fff" height="5" width="60" y="15"/></svg>',
 de:'<svg viewBox="0 0 60 36"><rect fill="#000" height="12" width="60"/><rect fill="#DD0000" height="12" width="60" y="12"/><rect fill="#FFCE00" height="12" width="60" y="24"/></svg>',
 fr:'<svg viewBox="0 0 60 36"><rect fill="#0055A4" height="36" width="20"/><rect fill="#fff" height="36" width="20" x="20"/><rect fill="#EF4135" height="36" width="20" x="40"/></svg>',
 ro:'<svg viewBox="0 0 60 36"><rect fill="#002B7F" height="36" width="20"/><rect fill="#FCD116" height="36" width="20" x="20"/><rect fill="#CE1126" height="36" width="20" x="40"/></svg>',
 it:'<svg viewBox="0 0 60 36"><rect fill="#009246" height="36" width="20"/><rect fill="#fff" height="36" width="20" x="20"/><rect fill="#CE2B37" height="36" width="20" x="40"/></svg>',
 pt:'<svg viewBox="0 0 60 36"><rect fill="#046A38" height="36" width="24"/><rect fill="#DA291C" height="36" width="36" x="24"/><circle cx="24" cy="18" fill="#FFCD00" r="6"/></svg>',
 nl:'<svg viewBox="0 0 60 36"><rect fill="#AE1C28" height="12" width="60"/><rect fill="#fff" height="12" width="60" y="12"/><rect fill="#21468B" height="12" width="60" y="24"/></svg>',
 pl:'<svg viewBox="0 0 60 36"><rect fill="#fff" height="18" width="60"/><rect fill="#DC143C" height="18" width="60" y="18"/></svg>'
};
function paintLangButtons(){const label=$('#langCurrentLabel');if(label)label.textContent=LANG_NAMES[currentLang()]||'English';const flag=$('#langCurrentFlag');if(flag)flag.innerHTML=LANG_FLAGS[currentLang()]||LANG_FLAGS.en}
function openLangPicker(){
 const overlay=document.createElement('div');overlay.className='room-type-dialog';
 overlay.innerHTML=`<div class="room-type-sheet"><div class="row" style="justify-content:space-between;align-items:center"><h2 style="margin:0">${t('msg.languageHeading')}</h2><button class="btn" id="closeLangPicker">×</button></div>${Object.keys(LANG_NAMES).map(code=>`<button type="button" class="lang-picker-item ${code===currentLang()?'active':''}" data-lang="${code}"><span class="lang-picker-flag">${LANG_FLAGS[code]}</span><span class="lang-picker-name">${LANG_NAMES[code]}</span>${code===currentLang()?'<span>✓</span>':'<span></span>'}</button>`).join('')}</div>`;
 document.body.appendChild(overlay);
 overlay.querySelector('#closeLangPicker').onclick=()=>overlay.remove();
 overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};
 overlay.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{setLang(b.dataset.lang);overlay.remove()});
}
function applyI18n(){$$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});$$('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder)});$$('[data-i18n-title]').forEach(el=>{el.title=t(el.dataset.i18nTitle)});$$('[data-i18n-aria]').forEach(el=>{el.setAttribute('aria-label',t(el.dataset.i18nAria))})}
